from thefuck.utils import for_app, replace_argument


@for_app('php')
def match(command):
    script_text = command.script
    return script_text.find("php -s") != -1


def get_new_command(command):
    old_flag = "-s"
    new_flag = "-S"
    return replace_argument(command.script, old_flag, new_flag)


